def get_profile(domain):
    """获取某个赛道的配置，若没有定制则返回默认"""
    base = DEFAULT_PROFILE.copy()
    if domain in CUSTOM_PROFILES:
        for key, val in CUSTOM_PROFILES[domain].items():
            base[key] = val
    return base

# ---------- 工具函数 ----------
def bounded(value, minimum=0.0, maximum=1.0):
    return max(minimum, min(maximum, value))

def json_text(items):
    return json.dumps(items, ensure_ascii=False)

def pick(items, seed):
    return items[seed % len(items)]

# ---------- 生成扩展案例 ----------
def generate_expanded_cases(count_per_domain=40):
    """
    为每个赛道生成 count_per_domain 条案例，确保覆盖所有前端选项。
    返回一个包含所有新增案例的字典列表。
    """
    new_cases = []
    case_id = 1  # 注意：实际插入时 ID 会与原始数据合并去重，这里仅作为生成基数，后续会重置

    for domain in ALL_DOMAINS:
        profile = get_profile(domain)
        topics = profile["topics"]
        entities = profile["entities"]
        # 若某些字段缺失，使用默认
        aud_list = profile.get("audiences", DEFAULT_PROFILE["audiences"])
        goal_list = profile.get("goals", DEFAULT_PROFILE["goals"])
        struct_list = profile.get("structures", DEFAULT_PROFILE["structures"])

        for i in range(count_per_domain):
            # 随机选择质量等级（保证各种类型都有）
            tier = random.choice(QUALITY_TIERS)
            platform = random.choice(PLATFORMS)
            hook = random.choice(ALL_HOOKS)
            audience = random.choice(aud_list)
            goal = random.choice(goal_list)
            structure = random.choice(struct_list)
            scenario = random.choice(ALL_SCENARIOS)
            topic = random.choice(topics)
            entity1 = random.choice(entities)
            entity2 = random.choice(entities)
            if entity2 == entity1:
                entity2 = random.choice(entities)

            # 构造标题和脚本摘要
            title = f"{topic}｜{platform}版{i+1:02d} — {random.choice(['真实案例', '避坑指南', '详细步骤', '经验分享', '深度测评'])}"
            if "低表现" in tier["label"] or "争议" in tier["label"]:
                title = f"{topic}（教训复盘）｜{platform}版{i+1:02d}"
            script = (
                f"开头以{hook}引入{topic}，中段展示{entity1}和{entity2}，"
                f"按照{structure}组织内容，结尾结合{audience}给出{scenario}下的行动建议。"
            )

            # 模拟数据
            views = int(tier["views"] * (0.7 + random.random() * 0.6))
            likes = int(views * tier["like_rate"] * (0.8 + random.random() * 0.4))
            comments = int(views * tier["comment_rate"] * (0.7 + random.random() * 0.6))
            shares = int(views * tier["share_rate"] * (0.7 + random.random() * 0.6))
            collects = int(views * tier["collect_rate"] * (0.7 + random.random() * 0.6))
            duration = 30 + random.randint(0, 150)
            base_score = tier["base"] + random.uniform(-3, 3)
            percentile = tier["percentile"] + random.uniform(-0.03, 0.03)
            percentile = bounded(percentile, 0.01, 0.99)
            completion = tier["completion"] + random.uniform(-0.05, 0.05)
            completion = bounded(completion, 0.2, 0.85)
            sentiment = bounded(random.uniform(0.3, 0.8))
            pain = bounded(random.uniform(0.4, 0.9))
            novelty = bounded(random.uniform(0.3, 0.8))
            trust = bounded(tier["trust"] + random.uniform(-0.1, 0.1))
            interaction = bounded(tier["interaction"] + random.uniform(-0.1, 0.1))

            tags = list(dict.fromkeys([domain, topic, platform, goal, structure, random.choice(["干货", "避雷", "攻略", "测评"])]))
            entities_list = list(dict.fromkeys([entity1, entity2, topic, random.choice(["真实数据", "用户反馈", "操作指南"])]))

            # 生成发布时间（随机日期）
            month = random.randint(1, 12)
            day = random.randint(1, 28)
            hour = random.randint(8, 23)
            minute = random.randint(0, 59)
            publish_time = f"2026-{month:02d}-{day:02d} {hour:02d}:{minute:02d}:00"

            new_cases.append({
                "id": str(case_id),
                "title": title,
                "script": script,
                "platform": platform,
                "publish_time": publish_time,
                "domain": domain,
                "audience": audience,
                "goal": goal,
                "structure": structure,
                "duration": str(duration),
                "base_score": f"{base_score:.2f}",
                "class_label": tier["label"],
                "percentile": f"{percentile:.3f}",
                "views": str(views),
                "likes": str(likes),
                "comments": str(comments),
                "shares": str(shares),
                "collects": str(collects),
                "completion": f"{completion:.3f}",
                "tags_json": json_text(tags),
                "entities_json": json_text(entities_list),
                "sentiment": f"{sentiment:.3f}",
                "hook": hook,
                "pain": f"{pain:.3f}",
                "novelty": f"{novelty:.3f}",
                "trust": f"{trust:.3f}",
                "interaction": f"{interaction:.3f}",
                "risk": tier["risk"],
                "scenario": scenario,
            })
            case_id += 1

    return new_cases

