def parse_case_records(data_text):
    return list(csv.DictReader(StringIO(data_text.strip()), delimiter="|"))

def read_case_records():
    base_records = parse_case_records(CASE_DATA)
    added_records = parse_case_records(ADDED_CASE_DATA)
    # 验证长度（原文件保证各100条）
    return base_records + added_records

def decimal_value(row, key):
    return Decimal(row[key])

def rate(part, whole):
    if whole <= 0:
        return Decimal("0.000")
    return (Decimal(part) / Decimal(whole)).quantize(Decimal("0.001"))

def build_case_rows(all_records):
    """将记录列表转换为数据库插入所需的三组元组"""
    base_rows = []
    metric_rows = []
    feature_rows = []

    for row in all_records:
        case_id = int(row["id"])
        views = int(row["views"])
        likes = int(row["likes"])
        comments = int(row["comments"])
        shares = int(row["shares"])
        collects = int(row["collects"])
        engagement_rate = (
            rate(likes, views)
            + rate(comments, views)
            + rate(shares, views)
            + rate(collects, views)
        ).quantize(Decimal("0.001"))

        base_rows.append((
            case_id,
            row["title"],
            row["script"],
            row["platform"],
            row["publish_time"],
            row["domain"],
            row["audience"],
            row["goal"],
            row["structure"],
            int(row["duration"]),
            decimal_value(row, "base_score"),
            row["class_label"],
            decimal_value(row, "percentile"),
            views,
            likes,
        ))
        metric_rows.append((
            case_id,
            case_id,
            comments,
            shares,
            collects,
            decimal_value(row, "completion"),
            rate(likes, views),
            rate(comments, views),
            rate(shares, views),
            rate(collects, views),
            engagement_rate,
        ))
        feature_rows.append((
            case_id,
            case_id,
            row["tags_json"],
            row["entities_json"],
            decimal_value(row, "sentiment"),
            row["hook"],
            decimal_value(row, "pain"),
            decimal_value(row, "novelty"),
            decimal_value(row, "trust"),
            decimal_value(row, "interaction"),
            row["risk"],
            row["scenario"],
        ))
    return base_rows, metric_rows, feature_rows

# ---------- 数据库初始化 ----------
def init_case_base_table():
    connection = None
    try:
        connection = mysql.connector.connect(**DB_CONFIG)
        cursor = connection.cursor()
        print(f"✅ 成功连接数据库: {DB_CONFIG['database']}")

        # 创建表
        cursor.execute("SET FOREIGN_KEY_CHECKS = 0;")
        for sql in CREATE_TABLES_SQL:
            cursor.execute(sql)
        cursor.execute("SET FOREIGN_KEY_CHECKS = 1;")

        # 读取原始种子（200条）
        seed_records = read_case_records()
        # 生成扩展案例（每个赛道40条，共920条）
        expanded_records = generate_expanded_cases(count_per_domain=40)

        # 合并，并重新分配ID（确保不冲突）
        all_records = seed_records + expanded_records
        # 重新编号（从1开始，但原始ID可能重复，直接重新分配）
        for idx, rec in enumerate(all_records, start=1):
            rec["id"] = str(idx)

        # 转换为插入元组
        base_rows, metric_rows, feature_rows = build_case_rows(all_records)

        # 插入数据
        cursor.executemany(
            """
            INSERT INTO Video_Case_Base
            (CaseId, Title, ScriptSummary, Platform, PublishTime, Domain, AudienceSegment, ContentGoal, ContentStructure,
             DurationSec, BaseScore, ClassLabel, Percentile, Views, Likes)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """,
            base_rows,
        )
        cursor.executemany(
            """
            INSERT INTO Video_Case_Metrics
            (MetricId, CaseId, Comments, Shares, Collects, CompletionRate, LikeRate, CommentRate, ShareRate, CollectRate, EngagementRate)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """,
            metric_rows,
        )
        cursor.executemany(
            """
            INSERT INTO Video_Case_Features
            (FeatureId, CaseId, TagsJson, CoreEntitiesJson, SentimentScore, HookType, PainPointIntensity, NoveltyScore,
             TrustEvidenceScore, InteractionIntent, RiskLevel, Scenario)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """,
            feature_rows,
        )

        connection.commit()
        print(f"🎉 案例库已成功写入 {len(base_rows)} 条案例，涵盖所有前端下拉选项。")

    except (Error, ValueError, json.JSONDecodeError) as e:
        print(f"❌ 数据库错误: {e}")
        if connection:
            connection.rollback()
    finally:
        if connection and connection.is_connected():
            if "cursor" in locals():
                cursor.close()
            connection.close()
            print("🔒 数据库连接已关闭。")

if __name__ == "__main__":
    # 设置随机种子确保可重复性（可选）
    random.seed(42)
    init_case_base_table()